class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        res, opened = [], 0
        for c in s:
            if c == '(':
                if opened > 0: res.append(c)
                opened += 1
            else:
                opened -= 1
                if opened > 0: res.append(c)
        return ''.join(res)

class Solution:
    def sumRootToLeaf(self, root) -> int:
        def dfs(node, val):
            if not node: return 0
            val = val * 2 + node.val
            if not node.left and not node.right: return val
            return dfs(node.left, val) + dfs(node.right, val)
        return dfs(root, 0)

class Solution:
    def camelMatch(self, queries, pattern: str):
        def match(q, p):
            j = 0
            for c in q:
                if j < len(p) and c == p[j]: j += 1
                elif c.isupper(): return False
            return j == len(p)
        return [match(q, pattern) for q in queries]

class Solution:
    def videoStitching(self, clips, time: int) -> int:
        clips.sort()
        res, end, far = 0, 0, 0
        i = 0
        while end < time:
            while i < len(clips) and clips[i][0] <= end:
                far = max(far, clips[i][1])
                i += 1
            if far == end: return -1
            end = far
            res += 1
        return res

