class Solution:
    def maxAncestorDiff(self, root) -> int:
        def dfs(node, mn, mx):
            if not node: return mx - mn
            mn, mx = min(mn, node.val), max(mx, node.val)
            return max(dfs(node.left, mn, mx), dfs(node.right, mn, mx))
        return dfs(root, root.val, root.val)

