class Solution:
    def maxSumTwoNoOverlap(self, nums, firstLen, lastLen) -> int:
        def helper(L, M):
            n = len(nums)
            p = [0]*(n+1)
            for i in range(n): p[i+1]=p[i]+nums[i]
            res, maxL = 0, 0
            for i in range(L+M, n+1):
                maxL = max(maxL, p[i-M]-p[i-M-L])
                res = max(res, maxL+p[i]-p[i-M])
            return res
        return max(helper(firstLen,lastLen), helper(lastLen,firstLen))

class StreamChecker:
    def __init__(self, words):
        self.trie = {}
        self.stream = []
        for w in words:
            node = self.trie
            for c in reversed(w):
                node = node.setdefault(c, {})
            node['#'] = True
    def query(self, letter: str) -> bool:
        self.stream.append(letter)
        node = self.trie
