            if '#' in node: return True
        return False

class Solution:
    def colorBorder(self, grid, row, col, color):
        m, n = len(grid), len(grid[0])
        orig = grid[row][col]
        visited = set()
        border = []
        def dfs(r, c):
            if (r,c) in visited: return
            visited.add((r,c))
            is_border = False
            for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n:
                    if grid[nr][nc] == orig: dfs(nr,nc)
                    elif (nr,nc) not in visited: is_border = True
                else: is_border = True
            if is_border: border.append((r,c))
        dfs(row, col)
        for r,c in border: grid[r][c] = color
        return grid

class Solution:
    def maxUncrossedLines(self, nums1, nums2) -> int:
        m, n = len(nums1), len(nums2)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(1,m+1):
            for j in range(1,n+1):
                if nums1[i-1]==nums2[j-1]: dp[i][j]=dp[i-1][j-1]+1
                else: dp[i][j]=max(dp[i-1][j],dp[i][j-1])
        return dp[m][n]

class Solution:
    def isEscapePossible(self, blocked, source, target) -> bool:
        if not blocked: return True
        blocked = set(map(tuple, blocked))
        limit = len(blocked) * len(blocked) // 2
        def bfs(start, end):
            queue, visited = [start], {tuple(start)}
            for x, y in queue:
                if [x,y] == end: return True
                if len(visited) > limit: return True
                for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = x+dx, y+dy
                    if 0<=nx<10**6 and 0<=ny<10**6 and (nx,ny) not in blocked and (nx,ny) not in visited:
                        visited.add((nx,ny))
                        queue.append((nx,ny))
            return False
        return bfs(source, target) and bfs(target, source)

