class Solution:
    def minScoreTriangulation(self, values) -> int:
        n = len(values)
        dp = [[0]*n for _ in range(n)]
        for l in range(2, n):
            for i in range(n-l):
                j = i+l
                dp[i][j] = float('inf')
                for k in range(i+1, j):
                    dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j]+values[i]*values[k]*values[j])
        return dp[0][n-1]

class Solution:
    def numMovesStonesII(self, stones):
        stones.sort()
        n = len(stones)
        mx = max(stones[n-1]-stones[1], stones[n-2]-stones[0]) - (n-2)
        mn = n
        j = 0
        for i in range(n):
            while j < n and stones[j]-stones[i] < n: j += 1
            cnt = j - i
            if cnt == n-1 and stones[j-1]-stones[i] == n-2:
                mn = min(mn, 2)
            else:
                mn = min(mn, n-cnt)
        return [mn, mx]

