class Solution:
    def longestDupSubstring(self, s: str) -> str:
        from functools import reduce
        n, mod, base = len(s), (1<<61)-1, 131
        nums = [ord(c)-ord('a') for c in s]
        def check(L):
            h = reduce(lambda a,b: (a*base+b)%mod, nums[:L], 0)
            seen = {h}
            power = pow(base, L, mod)
            for i in range(1, n-L+1):
                h = (h*base - nums[i-1]*power + nums[i+L-1]) % mod
                if h in seen: return i
                seen.add(h)
            return -1
        lo, hi, res = 1, n-1, 0
        while lo <= hi:
            mid = (lo+hi)//2
            idx = check(mid)
            if idx != -1:
                res = idx
                lo = mid+1
            else: hi = mid-1
        return s[res:res+hi] if hi >= 1 else ''

class Solution:
    def lastStoneWeight(self, stones) -> int:
        import heapq
        h = [-s for s in stones]
        heapq.heapify(h)
        while len(h) > 1:
            a, b = -heapq.heappop(h), -heapq.heappop(h)
            if a != b: heapq.heappush(h, -(a-b))
        return -h[0] if h else 0

