class Solution:
    def maxSatisfied(self, customers, grumpy, minutes) -> int:
        base = sum(c for c,g in zip(customers, grumpy) if g==0)
        extra = sum(customers[i]*grumpy[i] for i in range(minutes))
        max_extra = extra
        for i in range(minutes, len(customers)):
            extra += customers[i]*grumpy[i] - customers[i-minutes]*grumpy[i-minutes]
            max_extra = max(max_extra, extra)
        return base + max_extra

class Solution:
    def rearrangeBarcodes(self, barcodes):
        from collections import Counter
        cnt = Counter(barcodes)
        sorted_items = sorted(cnt.items(), key=lambda x: -x[1])
        res = [0]*len(barcodes)
        idx = 0
        for val, freq in sorted_items:
            for _ in range(freq):
                res[idx] = val
                idx += 2
                if idx >= len(barcodes): idx = 1
        return res

