class Solution:
    def leadsToDestination(self, n, edges, source, destination) -> bool:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
        if graph[destination]: return False
        state = [0]*n  # 0:unvisited, 1:visiting, 2:visited
        def dfs(u):
            if state[u] == 1: return False
            if state[u] == 2: return True
            if not graph[u]: return u == destination
            state[u] = 1
            for v in graph[u]:
                if not dfs(v): return False
            state[u] = 2
            return True
        return dfs(source)

class Solution:
    def missingElement(self, nums, k: int) -> int:
        def missing(i):
            return nums[i] - nums[0] - i
        n = len(nums)
        if k > missing(n-1):
            return nums[-1] + k - missing(n-1)
        lo, hi = 0, n-1
        while lo < hi:
            mid = (lo+hi)//2
            if missing(mid) < k: lo = mid+1
            else: hi = mid
        return nums[lo-1] + k - missing(lo-1)

class Solution:
    def smallestEquivalentString(self, s1, s2, baseStr) -> str:
        parent = list(range(26))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra < rb: parent[rb] = ra
            else: parent[ra] = rb
        for a, b in zip(s1, s2):
            union(ord(a)-97, ord(b)-97)
        return ''.join(chr(find(ord(c)-97)+97) for c in baseStr)

class Solution:
    def longestRepeatingSubstring(self, s: str) -> int:
        n = len(s)
        def check(L):
            seen = set()
            for i in range(n-L+1):
                t = s[i:i+L]
                if t in seen: return True
                seen.add(t)
            return False
        lo, hi = 0, n-1
        while lo < hi:
            mid = (lo+hi+1)//2
            if check(mid): lo = mid
            else: hi = mid-1
        return lo

class Solution:
    def validSubarrays(self, nums) -> int:
        stack = []
        res = 0
        for i, num in enumerate(nums):
            while stack and nums[stack[-1]] > num:
                res += i - stack.pop()
            stack.append(i)
        while stack:
