class Solution:
    def assignBikes(self, workers, bikes) -> int:
        from functools import lru_cache
        n, m = len(workers), len(bikes)
        @lru_cache(None)
        def dp(i, mask):
            if i == n: return 0
            res = float('inf')
            for j in range(m):
                if not (mask & (1<<j)):
                    d = abs(workers[i][0]-bikes[j][0])+abs(workers[i][1]-bikes[j][1])
                    res = min(res, d + dp(i+1, mask|(1<<j)))
            return res
        return dp(0, 0)

class Solution:
    def digitsCount(self, d: int, low: int, high: int) -> int:
        def count(n):
            if n < 0: return 0
            res, pos = 0, 1
            while pos <= n:
                divider = pos * 10
                res += (n // divider) * pos
                cur = (n // pos) % 10
                if d == 0: res -= pos
                if cur > d: res += pos
                elif cur == d: res += n % pos + 1
                pos *= 10
            return res
        return count(high) - count(low - 1)

