class Solution:
    def addNegabinary(self, arr1, arr2):
        res, carry = [], 0
        i, j = len(arr1)-1, len(arr2)-1
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0: s += arr1[i]; i -= 1
            if j >= 0: s += arr2[j]; j -= 1
            res.append(s & 1)
            carry = -(s >> 1)
        while len(res) > 1 and res[-1] == 0: res.pop()
        return res[::-1]

class Solution:
    def numSubmatrixSumTarget(self, matrix, target) -> int:
        m, n = len(matrix), len(matrix[0])
        res = 0
        for r1 in range(m):
            col_sum = [0]*n
            for r2 in range(r1, m):
                for c in range(n):
                    col_sum[c] += matrix[r2][c]
                cnt = {0: 1}
                s = 0
                for v in col_sum:
                    s += v
                    res += cnt.get(s-target, 0)
                    cnt[s] = cnt.get(s, 0)+1
        return res

