class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        from collections import Counter
        cnt = Counter(tiles)
        def bt():
            total = 0
            for c in cnt:
                if cnt[c] > 0:
                    cnt[c] -= 1
                    total += 1 + bt()
                    cnt[c] += 1
            return total
        return bt()

class Solution:
    def sufficientSubset(self, root, limit: int):
        def dfs(node, total):
            if not node: return None
            total += node.val
            if not node.left and not node.right:
                return None if total < limit else node
            node.left = dfs(node.left, total)
            node.right = dfs(node.right, total)
            if not node.left and not node.right: return None
            return node
        return dfs(root, 0)
